package com.eventease.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;

// Student entity - represents a college student who registers for events
@Entity
@Table(name = "students")
public class Student {

    // Primary key - auto-generated by the database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Student's full name - cannot be empty
    @NotBlank(message = "Name is required")
    private String name;

    // Student's email - must be a valid email format
    @NotBlank(message = "Email is required")
    @Email(message = "Please enter a valid email")
    @Column(unique = true)
    private String email;

    // Student's password for login
    @NotBlank(message = "Password is required")
    private String password;

    // Student's department (e.g., Computer Science, Electronics)
    @NotBlank(message = "Department is required")
    private String department;

    // Student's year of study (1, 2, 3, or 4)
    @NotNull(message = "Year of study is required")
    @Positive(message = "Year must be a positive number")
    private Integer yearOfStudy;

    // Default constructor required by JPA
    public Student() {}

    // Getters and Setters
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }

    public String getName() { return name; }
    public void setName(String name) { this.name = name; }

    public String getEmail() { return email; }
    public void setEmail(String email) { this.email = email; }

    public String getPassword() { return password; }
    public void setPassword(String password) { this.password = password; }

    public String getDepartment() { return department; }
    public void setDepartment(String department) { this.department = department; }

    public Integer getYearOfStudy() { return yearOfStudy; }
    public void setYearOfStudy(Integer yearOfStudy) { this.yearOfStudy = yearOfStudy; }
}
